const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL ?? "";
// Service role key required: anon role lacks EXECUTE on match_documents() by default.
// This file is server-side only (API routes) — never imported in browser code.
const SUPABASE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY ?? "";
const EMBEDDING_SERVER_URL = (
  process.env.EMBEDDING_SERVER_URL ?? "http://localhost:8001"
).replace(/\/+$/, "");

// Phase 7 (Voyage migration): when VOYAGE_API_KEY is set, embeddings are
// generated by Voyage (`voyage-3-lite` → 512 dims) instead of the local
// micro-server. The local path is retained as a backwards-compatible fallback
// until the Supabase `documents.embedding` column is re-embroidered to 512 and
// EMBEDDING_SERVER_URL is decommissioned. See
// docs/superpowers/specs/2026-05-31-architectural-upgrades.md §1.
const VOYAGE_API_KEY = process.env.VOYAGE_API_KEY ?? "";
const VOYAGE_MODEL = process.env.VOYAGE_EMBEDDING_MODEL ?? "voyage-3-lite";

export type RAGFilter = {
  subject?: string;
  grade?: number;
  topic?: string;
  curriculum?: string;
  country?: string;
};

export type RAGDocument = {
  id: string;
  content: string;
  metadata: Record<string, unknown>;
  similarity: number;
};

type EmbedServerResponse = {
  embeddings: number[][];
};

// ---------------------------------------------------------------------------
// Embedding
// ---------------------------------------------------------------------------

export async function embedQuery(text: string): Promise<number[]> {
  const trimmed = text.slice(0, 2000);

  // Phase 7: Voyage AI embeddings (default model `voyage-3-lite` → 512 dims).
  if (VOYAGE_API_KEY) {
    const res = await fetch("https://api.voyageai.com/v1/embeddings", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${VOYAGE_API_KEY}`,
      },
      body: JSON.stringify({ input: [trimmed], model: VOYAGE_MODEL }),
    });

    if (!res.ok) {
      throw new Error(`Voyage embedding failed with ${res.status}`);
    }

    const data = (await res.json()) as { data?: Array<{ embedding: number[] }> };
    const embedding = data.data?.[0]?.embedding;
    if (!Array.isArray(embedding) || embedding.length === 0) {
      throw new Error("Voyage returned no embedding.");
    }
    return embedding;
  }

  // Fallback: local embedding micro-server (pre-migration, 1536-dim).
  const res = await fetch(`${EMBEDDING_SERVER_URL}/embed`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ texts: [trimmed] }),
  });

  if (!res.ok) {
    throw new Error(`Embedding server responded with ${res.status}`);
  }

  const data = (await res.json()) as EmbedServerResponse;
  const embedding = data.embeddings?.[0];
  if (!Array.isArray(embedding) || embedding.length === 0) {
    throw new Error("Embedding server returned no vector.");
  }
  return embedding;
}

// ---------------------------------------------------------------------------
// Retrieval via Supabase PostgREST RPC
// ---------------------------------------------------------------------------

export async function retrieveDocuments(
  queryEmbedding: number[],
  filter: RAGFilter = {},
  matchThreshold = 0.7,
  matchCount = 5
): Promise<RAGDocument[]> {
  if (!SUPABASE_URL || !SUPABASE_KEY) {
    throw new Error("NEXT_PUBLIC_SUPABASE_URL and SUPABASE_ANON_KEY must be set.");
  }

  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/match_documents`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
    },
    body: JSON.stringify({
      query_embedding: queryEmbedding,
      match_threshold: matchThreshold,
      match_count: matchCount,
      filter: cleanFilter(filter),
    }),
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Supabase RPC error ${res.status}: ${text}`);
  }

  const data = (await res.json()) as unknown;
  return Array.isArray(data) ? (data as RAGDocument[]) : [];
}

// ---------------------------------------------------------------------------
// Semantic cache — deduplicates similar queries across all sessions
// ---------------------------------------------------------------------------

export type CachedResponse = {
  id: string;
  response: Record<string, unknown>;
  similarity: number;
};

type MatchCacheRow = {
  id: string;
  response: Record<string, unknown>;
  similarity: number;
};

function cleanFilter(filter: RAGFilter): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(filter).filter(([, v]) => v !== undefined && v !== null && v !== "")
  );
}

// Returns the closest cached response if cosine similarity ≥ threshold.
export async function checkSemanticCache(
  embedding: number[],
  filter: RAGFilter,
  threshold = 0.92
): Promise<CachedResponse | null> {
  if (!SUPABASE_URL || !SUPABASE_KEY) return null;

  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/match_cache`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
    },
    body: JSON.stringify({
      p_embedding: embedding,
      p_filter: cleanFilter(filter),
      p_threshold: threshold,
    }),
  });

  if (!res.ok) return null;
  const data = (await res.json()) as unknown;
  if (!Array.isArray(data) || data.length === 0) return null;
  return (data as MatchCacheRow[])[0] ?? null;
}

// Stores a query+response pair. Fire-and-forget — do not await in hot path.
export async function storeInSemanticCache(
  queryText: string,
  embedding: number[],
  filter: RAGFilter,
  response: Record<string, unknown>
): Promise<void> {
  if (!SUPABASE_URL || !SUPABASE_KEY) return;

  await fetch(`${SUPABASE_URL}/rest/v1/query_cache`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
      Prefer: "return=minimal",
    },
    body: JSON.stringify({
      query_text: queryText,
      query_embedding: embedding,
      filter: cleanFilter(filter),
      response,
    }),
  });
}

// Increments the hit counter without blocking the response.
export async function incrementCacheHits(id: string): Promise<void> {
  if (!SUPABASE_URL || !SUPABASE_KEY) return;

  await fetch(`${SUPABASE_URL}/rest/v1/rpc/increment_cache_hits`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
    },
    body: JSON.stringify({ p_id: id }),
  });
}

// ---------------------------------------------------------------------------
// Combined helper used by API routes
// ---------------------------------------------------------------------------

// CAPS is cumulative — a Grade 11 student asking about Newton's Laws needs
// Grade 10 content. Cascade from specific → subject-only → no filter until
// we find something, rather than returning nothing on an exact-grade miss.
export async function getRAGContext(
  query: string,
  filter: RAGFilter = {},
  matchCount = 5,
  precomputedEmbedding?: number[]
): Promise<{ context: string; sources: RAGDocument[] }> {
  const embedding = precomputedEmbedding ?? await embedQuery(query);

  // all-MiniLM-L6-v2 cosine similarity: 0.50–0.65 is a strong match for
  // domain-specific content. 0.70 is too strict — good docs get filtered out.

  // Pass 1: full filter (subject + grade + curriculum + country)
  let docs = await retrieveDocuments(embedding, filter, 0.50, matchCount);

  // Pass 2: drop grade — CAPS is cumulative, Grade 11 needs Grade 10 content
  if (docs.length === 0 && filter.grade) {
    const { grade: _grade, ...withoutGrade } = filter;
    docs = await retrieveDocuments(embedding, withoutGrade, 0.50, matchCount);
  }

  // Pass 3: pure semantic search — drop all filters, lower threshold
  // 0.38 is the floor for all-MiniLM-L6-v2 on CAPS academic content.
  // Below this, results become semantically unrelated.
  if (docs.length === 0) {
    docs = await retrieveDocuments(embedding, {}, 0.38, matchCount);
  }

  const context = docs.map((d) => d.content).join("\n\n---\n\n");
  return { context, sources: docs };
}
